draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw hills
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W, H);
  ctx.lineTo(W, H - 100 - 50 * Math.sin(t));
  ctx.lineTo(0, H - 100 - 50 * Math.cos(t));
  ctx.closePath();
  ctx.stroke();

  // draw trees
  ctx.beginPath();
  ctx.moveTo(W / 2 - 20, H - 150 - 20 * Math.sin(t));
  ctx.lineTo(W / 2 - 20, H - 50);
  ctx.lineTo(W / 2 + 20, H - 50);
  ctx.lineTo(W / 2 + 20, H - 150 - 20 * Math.sin(t));
  ctx.closePath();
  ctx.stroke();

  // draw sun
  ctx.beginPath();
  ctx.arc(W - 50, 50 + 20 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
